import {describe,it,expect} from 'vitest';
import fixture from '../../test/a14bRegionConformance.json';
import legacyFixture from '../../test/a14Conformance.json';
import {decodeProductSnapshot} from '../productEvidence/contracts';

// The ordering hazard this lane closes: `a14bRegionConformance.json` is the
// published bytes of a backend that already reduces reviewed coarse-region
// evidence (generated by `scripts/generate_a14b_region_conformance.py`). Before
// the route-explorer decoder widening, `decodeProductSnapshot` threw on this
// snapshot and the live route panel fell back to "Route projection
// unavailable"; the widening must stay load-bearing, so these cases decode the
// published bytes, keep the A14a eight-key shape decodable, and reject every
// split or widened-to-anything shape.
const published = () => structuredClone(fixture) as any;

describe('A14b coarse-region publishing against the route-explorer contract',()=>{
 it('decodes the backend-published region snapshot the browser receives',()=>{
  const snapshot=decodeProductSnapshot(published());
  const projection=snapshot.route_explorer!;
  expect(projection.regions).toHaveLength(3);
  expect(projection.nodes.map(node=>node.region).sort()).toEqual(['asia','europe','unknown']);
  const rows=new Map(projection.regions!.map(row=>[row.node,row]));
  for(const node of projection.nodes){
   const row=rows.get(node.id)!;
   expect(row.region).toBe(node.region);
   expect(row.region_source).toBe(node.region_source);
  }
  expect(rows.size).toBe(projection.nodes.length);
  expect(snapshot.coarse_region_evidence).toHaveLength(2);
 });

 it('keeps the A14a-era exact-eight-key projection decodable',()=>{
  const snapshot=decodeProductSnapshot(structuredClone(legacyFixture));
  expect(snapshot.route_explorer?.regions).toBeUndefined();
  expect(snapshot.route_explorer?.nodes.every(node=>node.region==='unknown'&&node.region_source==='unavailable')).toBe(true);
  expect(snapshot.coarse_region_evidence).toBeUndefined();
 });

 it('publishes a nine-key widening, so the backend alone would not decode',()=>{
  expect(Object.keys(fixture.route_explorer).sort()).toEqual(['digest','generation','nodes','overlays','protocol','regions','segments','source_digest','source_mode']);
  expect(fixture.route_explorer.nodes.some(node=>node.region!=='unknown')).toBe(true);
 });

 it('rejects a region row that disagrees with its node',()=>{
  const value=published();
  value.route_explorer.regions[0].region='polar';
  expect(()=>decodeProductSnapshot(value)).toThrow();
 });

 it('rejects a foreign node in the region rows',()=>{
  const value=published();
  value.route_explorer.regions[0].node='sha256:'+'c'.repeat(64);
  expect(()=>decodeProductSnapshot(value)).toThrow();
 });

 it('rejects short and duplicated region rows',()=>{
  const short=published();
  short.route_explorer.regions=short.route_explorer.regions.slice(0,1);
  expect(()=>decodeProductSnapshot(short)).toThrow();
  const duplicated=published();
  duplicated.route_explorer.regions=[...duplicated.route_explorer.regions,duplicated.route_explorer.regions[0]];
  expect(()=>decodeProductSnapshot(duplicated)).toThrow();
 });

 it('rejects coordinates, cells, and identity inside a region row',()=>{
  for(const field of ['latitude','longitude','cell','display_cell','endpoint_id','x','y']){
   const value=published();
   value.route_explorer.regions[0][field]='PRIVATE-CANARY';
   expect(()=>decodeProductSnapshot(value)).toThrow();
  }
 });

 it('rejects a non-vocabulary region and an unknown region source',()=>{
  const region=published();
  region.route_explorer.nodes[0].region='us-east-1';
  expect(()=>decodeProductSnapshot(region)).toThrow();
  const source=published();
  source.route_explorer.nodes[0].region_source='signed';
  expect(()=>decodeProductSnapshot(source)).toThrow();
  const blocker=published();
  blocker.route_explorer.regions[0].region_blocker='granted';
  expect(()=>decodeProductSnapshot(blocker)).toThrow();
 });

 it('rejects a tenth projection key',()=>{
  const value=published();
  value.route_explorer.prompt='PRIVATE-CANARY';
  expect(()=>decodeProductSnapshot(value)).toThrow();
 });

 it('rejects snapshot evidence that is not the closed reviewed record',()=>{
  const extra=published();
  extra.coarse_region_evidence[0].hostname='private.example';
  expect(()=>decodeProductSnapshot(extra)).toThrow();
  const geography=published();
  const latency=geography.coarse_region_evidence[1];
  Object.assign(latency,{source_kind:'latency_distance_class',uncertainty:'model_estimate',distance_class:'far',model_version:'latency_class_model_v1',region:'asia'});
  expect(()=>decodeProductSnapshot(geography)).toThrow();
  const uncertain=published();
  uncertain.coarse_region_evidence[0].uncertainty='reviewed';
  expect(()=>decodeProductSnapshot(uncertain)).toThrow();
 });
});
